@css:#single-content .article-content > :not(.heateorSssClear):not(.heateor_sss_sharing_container):not(.modown-ad):not(script):not(style):not(iframe):not(ins)@html<js>
var body = String(result).replace(/<img\b[^>]*>/gi, function (tag) {
    var original = tag.match(/\sdata-original="([^"]+)"/i) || tag.match(/\sdata-src="([^"]+)"/i);
    if (!original) return tag;
    return tag.replace(/\s(?:src|srcset)="[^"]*"/gi, '').replace(/^<img/i, function () { return '<img src="' + original[1] + '"'; });
});
if (!body.trim()) throw new Error('未找到帖子正文');
'<html><head><meta name="viewport" content="width=device-width, initial-scale=1"></head><body>' + body + '</body></html>'
</js>
